INSERT INTO environmental_destroy_sources (source_key,scenario_id,policy_version,template_reference,monster_reference,action_id,action_descriptor,descriptor_sha256,catalog_revision,public_proof,source_sha256) VALUES('installed-environmental-source-v1',-2245,'wakemu.original-body-namedtype-compatible-variant-v1',2536,5708,1359,'{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1359,"getDuration":0,"native_class":"aMg"}'::jsonb,'269a1588d2f0d93fc2596fa82372b5cbc087dac926412707f46a85d61a399c2a','b3963fc05f1d8ec1eb9afc268fab0350f4de120144d67f7eee470747750b2450','{"compatible_native_action_prototypes":[5708],"deterministic_named_type_proofs":[{"annotation":{"candidate_reference":2773,"candidate_sprite_id":158402773,"family_id":585,"proof_kind":"NATIVE_CQM_CONTENT38","selected_link":"IDENTICAL_ORIGINAL_SPRITE","selected_reference":5708,"selected_sprite_id":158402773,"source_matches":[{"fields":["24"],"language":"en","token":"Bworks"},{"fields":["24"],"language":"fr","token":"Bworks"},{"fields":["24"],"language":"es","token":"Bworks"}],"source_scenario_id":-2245,"status":"ACCEPTED","template_reference":2536},"candidate_reference":2773,"source_matches":[{"field":"24","language":"en","token":"Bworks"},{"field":"24","language":"fr","token":"Bworks"},{"field":"24","language":"es","token":"Bworks"}]}],"kind":"ORIGINAL_BODY_NAMEDTYPE_COMPATIBLE_VARIANT","matching_original_candidates":[{"family_id":585,"family_names":{"en":"Bworks","es":"Bworks","fr":"Bworks"},"names":{"en":"Cybwork","es":"Cybwork","fr":"Cybwork"},"native_destroy_action":null,"native_max_level":61,"native_min_level":61,"native_statistics":{"AP":{"base":9,"per_level":0.0},"HP":{"base":1004,"per_level":0.0},"INIT":{"base":54,"per_level":0.0},"MP":{"base":3,"per_level":0.0},"WP":{"base":0,"per_level":0.0}},"raw_visual_arrays":{"csb":[],"csc":[],"csu":[]},"reference":2773,"same_native_model_destroy_variants":[{"action":{"action_id":"1359","action_type":"3","criteria":"","duration":"0","family_id":"1149","max_level":"1","min_level":"1","name_en":"Pathetic Cybwork","name_fr":"Cybwork path\u00e9tique","native_cbH":"0","native_clx":"315","native_csI":"False","native_csJ":"True","native_csK":"False","reference_id":"5708"},"native_max_level":1,"native_min_level":1,"raw_visual_arrays":{"csb":[28],"csc":[20,13,7],"csu":[]},"reference":5708}],"source_name_literal_match":null,"sprite_id":158402773,"variant_authority":"Original named-type candidate; concrete variant is declared reconstruction unless independently proven exact."}],"native_action":{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1359,"getDuration":0,"native_class":"aMg"},"original_sources":{"localizations":{"en":{"24":"In their quest for fertility, the Bworks of the swamp went looking for males from other lands. Unfortunately, the only male Bworks they''ve been able to find are from a much lower caste than their own, and they''ve never managed to produce any offspring... Their women''s method of explaining to their partners that they''re not satisfied with them is just as interesting. The woman will throw the man out of her house and then threaten him, dissuading him from coming back. You don''t know what will become of these little Bworks, but you''d better take care of them, just in case. Interact with them the indicated number of times to collect the reward.","26":"Solo: The Lowly","28":"Interact with the monsters"},"es":{"24":"En su busca de la fertilidad, las bworks del pantano fueron a buscar individuos masculinos en otros lugares. Por desgracia, los \u00fanicos bworks machos que encontraron eran de una casta mucho m\u00e1s d\u00e9bil que la suya, as\u00ed que no pudieron tener ninguna descendencia. Su m\u00e9todo para explicar al compa\u00f1ero que no les gusta es interesante: consiste en echarlo de casa y amenazarlo para que no piense en volver. No sabes qu\u00e9 pasar\u00e1 con esos peque\u00f1os bworks, pero, ante la duda, ser\u00e1 mejor que te ocupes de ellos. Interact\u00faa con estos monstruos el n\u00famero de veces indicado para obtener la recompensa.","26":"Solo: Los subalternos","28":"Interactuar con los monstruos"},"fr":{"24":"Dans leur qu\u00eate de fertilit\u00e9, les Bworks du marais sont all\u00e9 chercher des individus masculins dans d''autres contr\u00e9es. Malheureusement, les seuls Bworks m\u00e2les qu''elles ont pu d\u00e9nicher sont d''une caste bien plus faible que la leur, elles n''ont jamais r\u00e9ussi \u00e0 en tirer une quelconque descendance... Leur m\u00e9thode pour expliquer \u00e0 son partenaire qu''il ne nous satisfait pas est toute aussi int\u00e9ressante : elle consiste \u00e0 jeter celui-ci hors de chez elles puis \u00e0 le menacer pour le dissuader de revenir. Vous ne savez pas ce que ces petits Bworks vont devenir, mais dans le doute il vaudrait mieux que vous vous en occupiez. Interagissez avec eux le nombre fois indiqu\u00e9 pour obtenir la r\u00e9compense.","26":"Solo : Les subalternes","28":"Interagir avec les monstres"}},"scenario_id":-2245},"original_template_membership_recovered":false,"reconstruction":"User-authorized named-type native variant, not original template membership","selected_species":{"family_id":1149,"illustration_id":-1,"loot_definitions":[],"max_level":1,"min_level":1,"name":"Cybwork pat\u00e9tico","native_abilities":[{"level_parameter":-1,"spell_id":4016},{"level_parameter":-1,"spell_id":4017},{"level_parameter":-1,"spell_id":4018}],"raw_visual_arrays":{"csb":[28],"csc":[20,13,7],"csu":[]},"ref":5708,"sprite_id":158402773,"statistics":{"AP":{"base":9,"per_level":0.0},"HP":{"base":22293,"per_level":200.0},"INIT":{"base":54,"per_level":0.0},"MP":{"base":3,"per_level":0.0},"WP":{"base":0,"per_level":0.0}}},"taxonomy_family_ids":[584,585,586],"taxonomy_proof":"blj.dvY/dvZ -> cqM -> DQ/DR -> aTF.a/b(38, familyID)","variant_selection":"positive-native-HP; direct candidate before identical sprite bridge; minimum native reference"}'::jsonb,'a316047a9d1163469bcd708e93669b284123ae3bc8c3a5fa0f2d0973112f5e1a');
