INSERT INTO environmental_destroy_sources (source_key,scenario_id,policy_version,template_reference,monster_reference,action_id,action_descriptor,descriptor_sha256,catalog_revision,public_proof,source_sha256) VALUES('installed-environmental-source-v1',-2232,'wakemu.original-body-namedtype-compatible-variant-v1',2527,5704,1355,'{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1355,"getDuration":0,"native_class":"aMg"}'::jsonb,'52075ff7b7d1d5305efe9d2044fcf7c19b06123e6b6a767d3b79621357baad8c','b3963fc05f1d8ec1eb9afc268fab0350f4de120144d67f7eee470747750b2450','{"compatible_native_action_prototypes":[5704],"deterministic_named_type_proofs":[{"annotation":{"candidate_reference":5477,"candidate_sprite_id":1111905477,"family_id":1119,"proof_kind":"NATIVE_CQM_CONTENT38","selected_link":"IDENTICAL_ORIGINAL_SPRITE","selected_reference":5704,"selected_sprite_id":1111905477,"source_matches":[{"fields":["24"],"language":"es","token":"Aren\u00f3pteros"}],"source_scenario_id":-2232,"status":"ACCEPTED","template_reference":2527},"candidate_reference":5477,"source_matches":[{"field":"24","language":"es","token":"Aren\u00f3pteros"}]}],"kind":"ORIGINAL_BODY_NAMEDTYPE_COMPATIBLE_VARIANT","matching_original_candidates":[{"family_id":1119,"family_names":{"en":"Sandyoptera","es":"Aren\u00f3pteros","fr":"Sabl\u00e9opt\u00e8res"},"names":{"en":"Looterbug","es":"Chaqueador","fr":"Pillheurt"},"native_destroy_action":null,"native_max_level":147,"native_min_level":143,"native_statistics":{"AP":{"base":12,"per_level":0.0},"HP":{"base":5600,"per_level":117.0},"INIT":{"base":180,"per_level":3.0},"MP":{"base":5,"per_level":0.0},"WP":{"base":0,"per_level":0.0}},"raw_visual_arrays":{"csb":[],"csc":[],"csu":[]},"reference":5477,"same_native_model_destroy_variants":[{"action":{"action_id":"1355","action_type":"3","criteria":"","duration":"0","family_id":"1149","max_level":"1","min_level":"1","name_en":"Loot-Hungry Looterbug","name_fr":"Pillheurt pilleur","native_cbH":"0","native_clx":"315","native_csI":"False","native_csJ":"True","native_csK":"False","reference_id":"5704"},"native_max_level":1,"native_min_level":1,"raw_visual_arrays":{"csb":[28],"csc":[20,13,7],"csu":[]},"reference":5704}],"source_name_literal_match":null,"sprite_id":1111905477,"variant_authority":"Original named-type candidate; concrete variant is declared reconstruction unless independently proven exact."}],"native_action":{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1355,"getDuration":0,"native_class":"aMg"},"original_sources":{"localizations":{"en":{"24":"The Bworks don''t show much restraint when it comes to their Muvegitant imports. As it happens, they sometimes inadvertently capture Sandyopteras, which are looking for something to eat themselves. Needless to say, they can''t survive for long in a swamp, so they head straight for the closest arid area seeking refuge. Over time, their numbers are beginning to grow too much, and they''re causing problems on the surface instead of staying underground. Interact with them the indicated number of times to collect the reward.","26":"Solo: Savannah Insects","28":"Interact with the monsters"},"es":{"24":"Las bworks no importan verdutantes con especial parsimonia. De hecho, por error capturan tambi\u00e9n aren\u00f3pteros, que tambi\u00e9n buscan algo que echarse a la boca. Est\u00e1 claro que no pueden sobrevivir mucho tiempo en un pantano, as\u00ed que se refugian en la zona \u00e1rida m\u00e1s cercana. Los a\u00f1os han hecho que su n\u00famero empiece a aumentar demasiado y que causen problemas en la superficie en vez de quedarse bajo tierra. Interact\u00faa con estos monstruos el n\u00famero de veces indicado para obtener la recompensa.","26":"Solo: Los insectos de la sabana","28":"Interactuar con los monstruos"},"fr":{"24":"Les imports de L\u00e9gumutants par les Bworks ne sont pas faits avec une grande parcimonie. En l''occurrence, il arrive qu''ils capturent par inadvertance des Sabl\u00e9opt\u00e8re, eux-m\u00eames en train de chercher \u00e0 se mettre quelque chose sous la dent. Il va sans dire qu''ils ne peuvent pas survivre bien longtemps dans un marais, ils se r\u00e9fugient donc directement dans la zone aride la plus proche. Les ann\u00e9es font que leur nombre commence \u00e0 trop grandir et qu''ils posent probl\u00e8me \u00e0 la surface au lieu de rester terr\u00e9s. Interagissez avec eux le nombre fois indiqu\u00e9 pour obtenir la r\u00e9compense.","26":"Solo : Les insectes de la savane","28":"Interagir avec les monstres"}},"scenario_id":-2232},"original_template_membership_recovered":false,"reconstruction":"User-authorized named-type native variant, not original template membership","selected_species":{"family_id":1149,"illustration_id":-1,"loot_definitions":[],"max_level":1,"min_level":1,"name":"Chaqueador saqueador","native_abilities":[{"level_parameter":-1,"spell_id":8031},{"level_parameter":-1,"spell_id":8032}],"raw_visual_arrays":{"csb":[28],"csc":[20,13,7],"csu":[]},"ref":5704,"sprite_id":1111905477,"statistics":{"AP":{"base":12,"per_level":0.0},"HP":{"base":24470,"per_level":200.0},"INIT":{"base":180,"per_level":3.0},"MP":{"base":5,"per_level":0.0},"WP":{"base":0,"per_level":0.0}}},"taxonomy_family_ids":[1118,1119],"taxonomy_proof":"blj.dvY/dvZ -> cqM -> DQ/DR -> aTF.a/b(38, familyID)","variant_selection":"positive-native-HP; direct candidate before identical sprite bridge; minimum native reference"}'::jsonb,'0a3feecae959e923ea76a3247e74e3473045de59f9d79f6d54ec7987f3a5fe6f');
