INSERT INTO environmental_destroy_sources (source_key,scenario_id,policy_version,template_reference,monster_reference,action_id,action_descriptor,descriptor_sha256,catalog_revision,public_proof,source_sha256) VALUES('installed-environmental-source-v1',-2219,'wakemu.original-body-namedtype-compatible-variant-v1',2518,5700,1358,'{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1358,"getDuration":0,"native_class":"aMg"}'::jsonb,'7a44e983a8a81f0edee0abb100865e060b064de1e7963fdd4604d24582380709','b3963fc05f1d8ec1eb9afc268fab0350f4de120144d67f7eee470747750b2450','{"compatible_native_action_prototypes":[5700],"deterministic_named_type_proofs":[{"annotation":{"candidate_reference":4203,"candidate_sprite_id":186604203,"family_id":866,"proof_kind":"NATIVE_CQM_CONTENT38","selected_link":"IDENTICAL_ORIGINAL_SPRITE","selected_reference":5700,"selected_sprite_id":186604203,"source_matches":[{"fields":["24"],"language":"fr","token":"Bl\u00e9rox"},{"fields":["24"],"language":"es","token":"Tejaroxores"}],"source_scenario_id":-2219,"status":"ACCEPTED","template_reference":2518},"candidate_reference":4203,"source_matches":[{"field":"24","language":"fr","token":"Bl\u00e9rox"},{"field":"24","language":"es","token":"Tejaroxores"}]}],"kind":"ORIGINAL_BODY_NAMEDTYPE_COMPATIBLE_VARIANT","matching_original_candidates":[{"family_id":866,"family_names":{"en":"Badgerox","es":"Tejaroxores","fr":"Bl\u00e9rox"},"names":{"en":"Badgeroxxor","es":"Rastrej\u00f3n","fr":"Fouirox"},"native_destroy_action":null,"native_max_level":195,"native_min_level":187,"native_statistics":{"AP":{"base":13,"per_level":0.0},"HP":{"base":12544,"per_level":305.0},"INIT":{"base":350,"per_level":0.0},"MP":{"base":5,"per_level":0.0},"WP":{"base":0,"per_level":0.0}},"raw_visual_arrays":{"csb":[28],"csc":[],"csu":[]},"reference":4203,"same_native_model_destroy_variants":[{"action":{"action_id":"1358","action_type":"3","criteria":"","duration":"0","family_id":"1149","max_level":"1","min_level":"1","name_en":"Unpredictable Badgeroxxor","name_fr":"Fouirox impr\u00e9visible","native_cbH":"0","native_clx":"315","native_csI":"False","native_csJ":"True","native_csK":"False","reference_id":"5700"},"native_max_level":1,"native_min_level":1,"raw_visual_arrays":{"csb":[28],"csc":[20,13,7],"csu":[]},"reference":5700}],"source_name_literal_match":null,"sprite_id":186604203,"variant_authority":"Original named-type candidate; concrete variant is declared reconstruction unless independently proven exact."}],"native_action":{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1358,"getDuration":0,"native_class":"aMg"},"original_sources":{"localizations":{"en":{"24":"Rocky climbs, a strange atmosphere... It''s as if you''re drawn to what you''re familiar with. Badgeroxes from a neighboring island are living up to this precept by taking refuge in Primount Canyon. There''s no telling what they''ll do, but they certainly don''t belong there. Interact with them the indicated number of times to collect the reward.","26":"Solo: Claws of the Canyon","28":"Interact with the monsters"},"es":{"24":"Pendientes rocosas, una atm\u00f3sfera extra\u00f1a, parece que nos atrae lo que ya conocemos. Unos tejaroxores procedentes de una isla cercana respetan ese precepto a pies juntillas: se han refugiado en el ca\u00f1\u00f3n de los primacizos. No sabemos qu\u00e9 piensan hacer, pero no pintan nada ah\u00ed. Interact\u00faa con estos monstruos el n\u00famero de veces indicado para obtener la recompensa.","26":"Solo: Las garras del ca\u00f1\u00f3n","28":"Interactuar con los monstruos"},"fr":{"24":"Des mont\u00e9es rocheuses, une ambiance \u00e9trange, il faut croire que l''on est attir\u00e9 par ce que l''on connait d\u00e9j\u00e0. Des Bl\u00e9rox venant d''une \u00eele voisine respectent parfaitement ce pr\u00e9cepte : ils se sont r\u00e9fugi\u00e9s dans le canyon des Primassifs. On ne peut pas savoir ce qu''ils vont faire, mais ils n''ont rien \u00e0 faire l\u00e0. Interagissez avec eux le nombre fois indiqu\u00e9 pour obtenir la r\u00e9compense.","26":"Solo : Les griffes du canyon","28":"Interagir avec les monstres"}},"scenario_id":-2219},"original_template_membership_recovered":false,"reconstruction":"User-authorized named-type native variant, not original template membership","selected_species":{"family_id":1149,"illustration_id":-1,"loot_definitions":[],"max_level":1,"min_level":1,"name":"Rastrej\u00f3n imprevisible","native_abilities":[{"level_parameter":-1,"spell_id":6067},{"level_parameter":-1,"spell_id":6073},{"level_parameter":-1,"spell_id":5891}],"raw_visual_arrays":{"csb":[28],"csc":[20,13,7],"csu":[]},"ref":5700,"sprite_id":186604203,"statistics":{"AP":{"base":13,"per_level":0.0},"HP":{"base":22851,"per_level":200.0},"INIT":{"base":350,"per_level":0.0},"MP":{"base":5,"per_level":0.0},"WP":{"base":0,"per_level":0.0}}},"taxonomy_family_ids":[866,870],"taxonomy_proof":"blj.dvY/dvZ -> cqM -> DQ/DR -> aTF.a/b(38, familyID)","variant_selection":"positive-native-HP; direct candidate before identical sprite bridge; minimum native reference"}'::jsonb,'e502dfabceda9c08f0c4081d4e8b6151654c24482b2e6b54bfb9ed1dc7d57947');
