INSERT INTO environmental_destroy_sources (source_key,scenario_id,policy_version,template_reference,monster_reference,action_id,action_descriptor,descriptor_sha256,catalog_revision,public_proof,source_sha256) VALUES('installed-environmental-source-v1',-1904,'wakemu.original-body-namedtype-compatible-variant-v1',2065,5067,1102,'{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1102,"getDuration":0,"native_class":"aMg"}'::jsonb,'9e1aa1d27ceb39ca459b0633131ee09070954be9da53b2b1000cb386d63b07f5','b3963fc05f1d8ec1eb9afc268fab0350f4de120144d67f7eee470747750b2450','{"compatible_native_action_prototypes":[5067],"deterministic_named_type_proofs":[{"annotation":{"candidate_reference":5067,"candidate_sprite_id":122,"language":"en","native_name":"Thirstin Hunga Gostof","native_name_token":"gostof","normalization":"NFKD accent removal; casefold; ASCII CamelCase boundary; exact word boundaries. Inflection pair explicitly stored; no fuzzy matching.","proof_kind":"EXPLICIT_NAMED_TYPE_TOKEN","selected_link":"DIRECT","selected_reference":5067,"selected_sprite_id":122,"source_fields":["24","26"],"source_scenario_id":-1904,"source_texts":{"24":"These Gostofs are trapped in the cemetery and their souls can''t rest until they''ve slaked their thirst. They''ll haunt the area for all eternity if you don''t give them one last sip of bamboo milk. Interact with them the number of times shown to collect the reward.","26":"Solo: Souser Gostofs"},"source_token":"gostofs","status":"ACCEPTED","template_reference":2065},"candidate_reference":5067,"source_matches":[{"field":"24","language":"en","token":"gostofs"},{"field":"26","language":"en","token":"gostofs"}]}],"kind":"ORIGINAL_BODY_NAMEDTYPE_COMPATIBLE_VARIANT","matching_original_candidates":[{"family_id":1034,"family_names":{"en":"Environmental Quests in Pandalucia","es":"Misiones autom\u00e1ticas de Pandaluc\u00eda","fr":"Qu\u00eates Environnementales de la Pandalousie"},"names":{"en":"Thirstin Hunga Gostof","es":"Gostofo Ting Hozed","fr":"Gostof Jay Swaf"},"native_destroy_action":{"action_id":"1102","action_type":"3","criteria":"","duration":"0","family_id":"1034","max_level":"1","min_level":"1","name_en":"Thirstin Hunga Gostof","name_fr":"Gostof Jay Swaf","native_cbH":"0","native_clx":"315","native_csI":"False","native_csJ":"True","native_csK":"False","reference_id":"5067"},"native_max_level":1,"native_min_level":1,"native_statistics":{"AP":{"base":6,"per_level":0.0},"HP":{"base":1,"per_level":0.0},"INIT":{"base":0,"per_level":0.0},"MP":{"base":3,"per_level":0.0},"WP":{"base":0,"per_level":0.0}},"raw_visual_arrays":{"csb":[],"csc":[13,20,7],"csu":[]},"reference":5067,"same_native_model_destroy_variants":[],"source_name_literal_match":null,"sprite_id":122,"variant_authority":"Original named-type candidate; concrete variant is declared reconstruction unless independently proven exact."}],"native_action":{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1102,"getDuration":0,"native_class":"aMg"},"original_sources":{"localizations":{"en":{"24":"These Gostofs are trapped in the cemetery and their souls can''t rest until they''ve slaked their thirst. They''ll haunt the area for all eternity if you don''t give them one last sip of bamboo milk. Interact with them the number of times shown to collect the reward.","26":"Solo: Souser Gostofs","28":"Interact with the monsters"},"es":{"24":"Los gostofos son prisioneros del cementerio, ya que su alma no puede encontrar el descanso eterno mientras que no hayan calmado su sed. Se aparecer\u00e1n en la zona durante toda la eternidad si no les das un \u00faltimo trago de leche de bamb\u00fa. Interact\u00faa con ellos el n\u00famero de veces indicado para obtener la recompensa.","26":"Solo: La sed de los gostofos","28":"Interactuar con los monstruos"},"fr":{"24":"Ces Gostofs sont prisonniers du cimeti\u00e8re, leur \u00e2me ne pouvant pas trouver le repos tant qu''ils n''auront pas \u00e9panch\u00e9 leur soif. Ils hanteront les lieux pour l''\u00e9ternit\u00e9 si vous ne leur accordez pas une ultime gorg\u00e9e de lait de bambou. Interagissez avec eux le nombre de fois indiqu\u00e9 pour obtenir la r\u00e9compense.","26":"Solo : Les Gostofs Swafards","28":"Interagir avec les monstres"}},"scenario_id":-1904},"original_template_membership_recovered":false,"reconstruction":"User-authorized named-type native variant, not original template membership","selected_species":{"family_id":1034,"illustration_id":101200122,"loot_definitions":[],"max_level":1,"min_level":1,"name":"Gostofo Ting Hozed","native_abilities":[],"raw_visual_arrays":{"csb":[],"csc":[13,20,7],"csu":[]},"ref":5067,"sprite_id":122,"statistics":{"AP":{"base":6,"per_level":0.0},"HP":{"base":1,"per_level":0.0},"INIT":{"base":0,"per_level":0.0},"MP":{"base":3,"per_level":0.0},"WP":{"base":0,"per_level":0.0}}},"taxonomy_family_ids":[],"taxonomy_proof":"blj.dvY/dvZ -> cqM -> DQ/DR -> aTF.a/b(38, familyID)","variant_selection":"positive-native-HP; direct candidate before identical sprite bridge; minimum native reference"}'::jsonb,'3cb593be9a8d594d4e62110104f49838c9c9fb41a2ff5d0594a41627fbecc2d8');
