INSERT INTO environmental_destroy_sources (source_key,scenario_id,policy_version,template_reference,monster_reference,action_id,action_descriptor,descriptor_sha256,catalog_revision,public_proof,source_sha256) VALUES('installed-environmental-source-v1',-1892,'wakemu.original-body-namedtype-compatible-variant-v1',2062,5064,1099,'{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1099,"getDuration":0,"native_class":"aMg"}'::jsonb,'c343a2c86466802e23e57487b3ef00386dc1f93fcba2cb0dcc4f5f889f4cfc3b','b3963fc05f1d8ec1eb9afc268fab0350f4de120144d67f7eee470747750b2450','{"compatible_native_action_prototypes":[5064],"deterministic_named_type_proofs":[{"annotation":{"candidate_reference":5064,"candidate_sprite_id":104000464,"language":"en","native_name":"Flexi Toad","native_name_token":"toad","normalization":"NFKD accent removal; casefold; ASCII CamelCase boundary; exact word boundaries. Inflection pair explicitly stored; no fuzzy matching.","proof_kind":"EXPLICIT_NAMED_TYPE_TOKEN","selected_link":"DIRECT","selected_reference":5064,"selected_sprite_id":104000464,"source_fields":["24","26"],"source_scenario_id":-1892,"source_texts":{"24":"Toads have taken up residence in the Pandalucian swamps. Everything was looking good for their integration in the ecosystem but they''re croaking up such a cacophony day and night they''ve become a nuisance. It''s time to teach them some manners! Interact with them the number of times shown to collect the reward.","26":"Solo: Polite Polyvalent Toads"},"source_token":"toads","status":"ACCEPTED","template_reference":2062},"candidate_reference":5064,"source_matches":[{"field":"24","language":"en","token":"toads"},{"field":"26","language":"en","token":"toads"}]}],"kind":"ORIGINAL_BODY_NAMEDTYPE_COMPATIBLE_VARIANT","matching_original_candidates":[{"family_id":1034,"family_names":{"en":"Environmental Quests in Pandalucia","es":"Misiones autom\u00e1ticas de Pandaluc\u00eda","fr":"Qu\u00eates Environnementales de la Pandalousie"}