INSERT INTO environmental_destroy_sources (source_key,scenario_id,policy_version,template_reference,monster_reference,action_id,action_descriptor,descriptor_sha256,catalog_revision,public_proof,source_sha256) VALUES('installed-environmental-source-v1',-1737,'wakemu.original-body-namedtype-compatible-variant-v1',1974,4975,1078,'{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1078,"getDuration":0,"native_class":"aMg"}'::jsonb,'b6aac75b83706ea074c6c0b86f1e128260e6d92c26078574d0828a75e356af85','b3963fc05f1d8ec1eb9afc268fab0350f4de120144d67f7eee470747750b2450','{"compatible_native_action_prototypes":[4975],"deterministic_named_type_proofs":[{"annotation":{"candidate_reference":4975,"candidate_sprite_id":177804162,"language":"en","native_name":"Polarized Kralien","native_name_token":"kralien","normalization":"NFKD accent removal; casefold; ASCII CamelCase boundary; exact word boundaries. Inflection pair explicitly stored; no fuzzy matching.","proof_kind":"EXPLICIT_NAMED_TYPE_TOKEN","selected_link":"DIRECT","selected_reference":4975,"selected_sprite_id":177804162,"source_fields":["24"],"source_scenario_id":-1737,"source_texts":{"24":"The presence of the Rogues in the mines has caused a feeling of oppression among the Kraliens, who have raised their internal electric currents dangerously high. Suck up to them a little to calm the current situation and avoid a massive extinction of these mollusks. Interact with each of them to collect the reward."},"source_token":"kraliens","status":"ACCEPTED","template_reference":1974},"candidate_reference":4975,"source_matches":[{"field":"24","language":"en","token":"kraliens"}]}],"kind":"ORIGINAL_BODY_NAMEDTYPE_COMPATIBLE_VARIANT","matching_original_candidates":[{"family_id":999,"family_names":{"en":"Environmental Quests in Sufokia","es":"Misiones autom\u00e1ticas de Sufokia","fr":"Qu\u00eates Environnementales de Sufokia"},"names":{"en":"Polarized Kralien","es":"Kralien polarizado","fr":"Kralien Polaris\u00e9"},"native_destroy_action":{"action_id":"1078","action_type":"3","criteria":"","duration":"0","family_id":"999","max_level":"1","min_level":"1","name_en":"Polarized Kralien","name_fr":"Kralien Polaris\u00e9","native_cbH":"0","native_clx":"315","native_csI":"False","native_csJ":"True","native_csK":"False","reference_id":"4975"},"native_max_level":1,"native_min_level":1,"native_statistics":{"AP":{"base":6,"per_level":0.0},"HP":{"base":1,"per_level":0.0},"INIT":{"base":0,"per_level":0.0},"MP":{"base":3,"per_level":0.0},"WP":{"base":0,"per_level":0.0}},"raw_visual_arrays":{"csb":[],"csc":[13,20,7],"csu":[]},"reference":4975,"same_native_model_destroy_variants":[],"source_name_literal_match":null,"sprite_id":177804162,"variant_authority":"Original named-type candidate; concrete variant is declared reconstruction unless independently proven exact."}],"native_action":{"aGJ":3,"cbH":0,"clT":"","clx":315,"csI":false,"csJ":true,"csK":false,"d":1078,"getDuration":0,"native_class":"aMg"},"original_sources":{"localizations":{"en":{"24":"The presence of the Rogues in the mines has caused a feeling of oppression among the Kraliens, who have raised their internal electric currents dangerously high. Suck up to them a little to calm the current situation and avoid a massive extinction of these mollusks. Interact with each of them to collect the reward.","26":"Collaborative: Static Kralectricity","28":"Interact with the monsters"},"es":{"24":"La presencia de los tymadores en las minas ha creado un sentimiento de opresi\u00f3n en casa de los kraliens, que han aumentado peligrosamente sus tensiones el\u00e9ctricas internas. M\u00edmalos un poco para que baje esta tensi\u00f3n y evites as\u00ed una extinci\u00f3n masiva de estos moluscos. Interact\u00faa con cada uno de ellos para obtener la recompensa.","26":"Colaborativo: Kralectricidad est\u00e1tica","28":"Interactuar con los monstruos"},"fr":{"24":"La pr\u00e9sence des Roublards dans les mines a cr\u00e9\u00e9 un sentiment d''oppresion chez les Kraliens, qui ont dangereusement augment\u00e9 leurs tensions \u00e9lectriques internes. Cajolez les donc un peu pour faire chuter cette tension et \u00e9viter une extinction massive de ces mollusques. Interagissez avec chacun d''entre eux pour obtenir la r\u00e9compense.","26":"Collaboratif : Kralectricit\u00e9 Statique","28":"Interagir avec les monstres"}},"scenario_id":-1737},"original_template_membership_recovered":false,"reconstruction":"User-authorized named-type native variant, not original template membership","selected_species":{"family_id":999,"illustration_id":-1,"loot_definitions":[],"max_level":1,"min_level":1,"name":"Kralien polarizado","native_abilities":[],"raw_visual_arrays":{"csb":[],"csc":[13,20,7],"csu":[]},"ref":4975,"sprite_id":177804162,"statistics":{"AP":{"base":6,"per_level":0.0},"HP":{"base":1,"per_level":0.0},"INIT":{"base":0,"per_level":0.0},"MP":{"base":3,"per_level":0.0},"WP":{"base":0,"per_level":0.0}}},"taxonomy_family_ids":[],"taxonomy_proof":"blj.dvY/dvZ -> cqM -> DQ/DR -> aTF.a/b(38, familyID)","variant_selection":"positive-native-HP; direct candidate before identical sprite bridge; minimum native reference"}'::jsonb,'c4a1ef8743ec40a9ba1ee1c654c9e64fb3f1ab4dbfc4f89fae763f2905e4e26a');
